def mirror_with_preserved_5(grid, divider_col, mark_pos=(0, divider_col + 3)):
    rows = len(grid)
    cols_total = len(grid[0])
    mark_col = divider_col + 3 if len(mark_pos) == 1 else mark_pos[1]

    result = [[0] * cols_total for _ in range(rows)]

    for r in range(rows):
        for c in range(divider_col):
            mirrored_c = divider_col + c
            if mirrored_c < cols_total:
                result[r][mirrored_c] = grid[r][c]

        result[r][divider_col] = grid[r][divider_col]

    if mark_pos[0] < rows and mark_col < cols_total:
        result[mark_pos[0]][mark_col] = 5

    return result

